/**
 * @summary Get chat messages for a show
 */
export const getGetChatMessagesUrl = (
  showId: number,
  params?: GetChatMessagesParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/chat/${showId}/messages?${stringifiedParams}`
    : `/api/chat/${showId}/messages`;
};

export const getChatMessages = async (
  showId: number,
  params?: GetChatMessagesParams,
  options?: RequestInit,
): Promise<ChatMessage[]> => {
  return customFetch<ChatMessage[]>(getGetChatMessagesUrl(showId, params), {
    ...options,
    method: "GET",
  });
};

export const getGetChatMessagesQueryKey = (
  showId: number,
  params?: GetChatMessagesParams,
) => {
  return [`/api/chat/${showId}/messages`, ...(params ? [params] : [])] as const;
};

export const getGetChatMessagesQueryOptions = <
  TData = Awaited<ReturnType<typeof getChatMessages>>,
  TError = ErrorType<unknown>,
>(
  showId: number,
  params?: GetChatMessagesParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getChatMessages>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetChatMessagesQueryKey(showId, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getChatMessages>>> = ({
    signal,
  }) => getChatMessages(showId, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!showId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getChatMessages>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

